package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.NameTransformer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

/**
 * Unit tests for BeanPropertyMap._rename method.
 * Since _rename is protected, we use a subclass or Mockito to access it.
 */
public class BeanPropertyMap__rename_TriageGen2Test {

    // Helper class to expose the protected method for testing
    private static class BeanPropertyMapTester extends BeanPropertyMap {
        protected BeanPropertyMapTester(boolean caseInsensitive, java.util.Collection<SettableBeanProperty> props) {
            super(caseInsensitive, props);
        }

        @Override
        public SettableBeanProperty _rename(SettableBeanProperty prop, NameTransformer xf) {
            return super._rename(prop, xf);
        }
    }

    @Test
    public void testRename_NullProperty() {
        BeanPropertyMapTester map = new BeanPropertyMapTester(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty result = map._rename(null, xf);

        assertNull(result);
        verifyNoInteractions(xf);
    }

    @Test
    public void testRename_SimpleNameTransformation() {
        BeanPropertyMapTester map = new BeanPropertyMapTester(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedProp = mock(SettableBeanProperty.class);

        when(prop.getName()).thenReturn("oldName");
        when(xf.transform("oldName")).thenReturn("newName");
        when(prop.withSimpleName("newName")).thenReturn(renamedProp);
        // Ensure deser is null to cover the branch where deser is null
        when(renamedProp.getValueDeserializer()).thenReturn(null);

        SettableBeanProperty result = map._rename(prop, xf);

        assertEquals(renamedProp, result);
        verify(prop).withSimpleName("newName");
    }

    @Test
    public void testRename_WithDeserializerUnwrapping() {
        BeanPropertyMapTester map = new BeanPropertyMapTester(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedProp = mock(SettableBeanProperty.class);

        // Mock Deserializer
        StdDeserializer<?> originalDeser = new StdDeserializer<Object>(Object.class) {};
        StdDeserializer<?> unwrappedDeser = new StdDeserializer<Object>(Object.class) {};

        when(prop.getName()).thenReturn("oldName");
        when(xf.transform("oldName")).thenReturn("newName");
        when(prop.withSimpleName("newName")).thenReturn(renamedProp);

        // Setup deserializer logic
        when(renamedProp.getValueDeserializer()).thenReturn(originalDeser);
        // Mock unwrapping behavior
        when(originalDeser.unwrappingDeserializer(xf)).thenReturn(unwrappedDeser);
        // Mock the creation of a new property with the new deserializer
        when(renamedProp.withValueDeserializer(unwrappedDeser)).thenReturn(renamedProp);

        SettableBeanProperty result = map._rename(prop, xf);

        assertEquals(renamedProp, result);
        verify(originalDeser).unwrappingDeserializer(xf);
        verify(renamedProp).withValueDeserializer(unwrappedDeser);
    }

    @Test
    public void testRename_WithDeserializerSameInstance() {
        BeanPropertyMapTester map = new BeanPropertyMapTester(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedProp = mock(SettableBeanProperty.class);

        StdDeserializer<?> deser = mock(StdDeserializer.class);

        when(prop.getName()).thenReturn("name");
        when(xf.transform("name")).thenReturn("name");
        when(prop.withSimpleName("name")).thenReturn(renamedProp);
        when(renamedProp.getValueDeserializer()).thenReturn(deser);

        // Simulate that unwrapping returns the exact same instance
        when(deser.unwrappingDeserializer(xf)).thenReturn(deser);

        SettableBeanProperty result = map._rename(prop, xf);

        assertEquals(renamedProp, result);
        // Verify withValueDeserializer is NOT called because newDeser == deser
        verify(renamedProp, never()).withValueDeserializer(any());
    }
}
